const input = $input.first().json.body ?? $input.first().json;
const allowedLanguages = ['es', 'en', 'fr', 'de', 'pt'];
const allowedRoles = ['USER', 'MODERATOR', 'ADMIN'];
const message = typeof input.message === 'string' ? input.message.trim() : '';
const language = allowedLanguages.includes(input.language) ? input.language : 'es';
const role = allowedRoles.includes(input.role) ? input.role : 'USER';
const valid = Boolean(message) && message.length <= 2000;
const requestId = input.requestId || `n8n-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
return [{ json: { valid, requestId, message, language, role, context: input.context && typeof input.context === 'object' ? { page: typeof input.context.page === 'string' ? input.context.page.slice(0, 80) : undefined, restorationZoneId: typeof input.context.restorationZoneId === 'string' ? input.context.restorationZoneId.slice(0, 120) : undefined } : {}, error: valid ? '' : 'INVALID_INPUT' } }];

const data = $input.first().json;
const context = JSON.stringify(data.context || {});
const system = `Eres el asistente virtual educativo del proyecto Restauración Coralina de Isla Tortuga, Costa Rica. Responde siempre en el idioma solicitado (${data.language}). Usa únicamente el contexto público entregado. Diferencia hechos de recomendaciones, no inventes información, indica cuando falta contexto, promueve turismo responsable y no des instrucciones que puedan dañar arrecifes o fauna marina. No diagnostiques enfermedades, no recomiendes intervenciones biológicas y no concedas permisos. Sé claro y conciso.`;
return [{ json: { ...data, system, contextText: context } }];

const provider = $input.first().json;
const answer = provider.choices?.[0]?.message?.content;
if (typeof answer !== 'string' || !answer.trim()) return [{ json: { success: false, answer: '', requestId: `n8n-${Date.now()}`, error: 'INVALID_RESPONSE' } }];
return [{ json: { success: true, answer: answer.trim(), requestId: `n8n-${Date.now()}`, sources: [] } }];
